// Access gate: the viewer only starts once the visitor enters the key whose salted
// PBKDF2 hash is in auth/auth.config.js (generated by auth/build-auth.mjs).
// A correct key is remembered for SESSION_MS (across tabs and reloads); after that
// the page goes back to the key screen, even if it is still open.
const SESSION_KEY = "hexa_auth";
const SESSION_MS = 60 * 60 * 1000;

// Same derivation as auth/build-auth.mjs: PBKDF2-SHA-256, 32 bytes, hex.
const derive = async (key, { salt, iterations }) => {
  const enc = new TextEncoder();
  const base = await crypto.subtle.importKey(
    "raw",
    enc.encode(key),
    "PBKDF2",
    false,
    ["deriveBits"],
  );
  const bits = await crypto.subtle.deriveBits(
    { name: "PBKDF2", hash: "SHA-256", salt: enc.encode(salt), iterations },
    base,
    256,
  );
  return [...new Uint8Array(bits)]
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
};

// Stored as { hash, expires }. localStorage can throw (blocked site data); then the
// key is asked on every load. An expired or unreadable entry is dropped.
const readSession = () => {
  try {
    const session = JSON.parse(localStorage.getItem(SESSION_KEY));
    if (session?.expires > Date.now()) return session;
    localStorage.removeItem(SESSION_KEY);
  } catch {}
  return null;
};
const writeSession = (hash) => {
  const session = { hash, expires: Date.now() + SESSION_MS };
  try {
    localStorage.setItem(SESSION_KEY, JSON.stringify(session));
  } catch {}
  return session;
};

// Back to the key screen once the session runs out. The timer can fire late
// (background tab, sleeping laptop), so it is re-checked when the tab is shown.
const expireAt = (expires) => {
  const relock = () => {
    if (Date.now() >= expires) location.reload();
  };
  setTimeout(relock, expires - Date.now());
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") relock();
  });
};

// Resolves once access is granted. Never resolves when the gate can't run
// (no config, insecure context), so nothing behind it loads.
export const unlock = async () => {
  const form = document.getElementById("auth");
  const input = document.getElementById("auth-key");
  const submit = document.getElementById("auth-submit");
  const error = document.getElementById("auth-error");
  const open = ({ expires }) => {
    form.hidden = true;
    document.body.classList.remove("locked");
    expireAt(expires);
  };
  const blocked = (message) => {
    form.hidden = false;
    input.disabled = submit.disabled = true;
    error.textContent = message;
    return new Promise(() => {});
  };

  let config;
  try {
    ({ AUTH: config } = await import("./auth.config.js"));
  } catch (err) {
    console.error(
      "Access gate is not configured (run node auth/build-auth.mjs):",
      err,
    );
    return blocked("Access isn't set up on this server yet.");
  }
  // WebCrypto only exists on https:// and localhost.
  if (!crypto.subtle) return blocked("Open this page over https to sign in.");
  const session = readSession();
  if (session?.hash === config.hash) return open(session);

  form.hidden = false;
  input.focus();
  return new Promise((resolve) => {
    form.addEventListener("submit", async (e) => {
      e.preventDefault();
      const key = input.value.trim();
      if (!key) return;
      submit.disabled = true;
      error.textContent = "";
      const hash = await derive(key, config);
      submit.disabled = false;
      if (hash !== config.hash) {
        error.textContent = "Incorrect password. Please check it and try again.";
        input.select();
        return;
      }
      open(writeSession(hash));
      resolve();
    });
  });
};
